#!/usr/bin/env python3\nimport tkinter as tk\nfrom tkinter import ttk, messagebox, filedialog\nimport subprocess\nimport threading\nimport os\nfrom datetime import datetime\nimport json\nfrom pathlib import Path\n\nclass LabControlPanel:\n    def __init__(self, root):\n        self.root = root\n        self.root.title(\"Advanced Mobile-Laptop Control Lab\")\n        self.root.geometry(\"900x700\")\n        self.root.configure(bg=\"#f0f0f0\")\n        \n        self.device_ip = tk.StringVar(value=\"192.168.1.25\")\n        self.device_port = tk.StringVar(value=\"5555\")\n        self.laptop_ip = tk.StringVar(value=\"192.168.1.50\")\n        self.laptop_user = tk.StringVar(value=\"user\")\n        self.output_text = None\n        self.is_running = False\n        \n        self.log_dir = Path.home() / \".lab-control\" / \"logs\"\n        self.log_dir.mkdir(parents=True, exist_ok=True)\n        \n        self.setup_ui()\n        self.load_config()\n    \n    def setup_ui(self):\n        # Header\n        header = ttk.Frame(self.root)\n        header.pack(fill=tk.X, padx=10, pady=10)\n        ttk.Label(header, text=\"🔧 Mobile-Laptop Control Lab\", font=(\"Arial\", 16, \"bold\")).pack(side=tk.LEFT)\n        \n        # Notebook (Tabs)\n        notebook = ttk.Notebook(self.root)\n        notebook.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)\n        \n        # Tab 1: Device Configuration\n        config_frame = ttk.Frame(notebook)\n        notebook.add(config_frame, text=\"Device Configuration\")\n        self.setup_config_tab(config_frame)\n        \n        # Tab 2: Android Controls\n        android_frame = ttk.Frame(notebook)\n        notebook.add(android_frame, text=\"Android Controls\")\n        self.setup_android_tab(android_frame)\n        \n        # Tab 3: Laptop Access\n        laptop_frame = ttk.Frame(notebook)\n        notebook.add(laptop_frame, text=\"Laptop Access\")\n        self.setup_laptop_tab(laptop_frame)\n        \n        # Tab 4: Monitoring\n        monitor_frame = ttk.Frame(notebook)\n        notebook.add(monitor_frame, text=\"Monitoring & Logs\")\n        self.setup_monitor_tab(monitor_frame)\n        \n        # Output Console\n        console_label = ttk.Label(self.root, text=\"Console Output:\", font=(\"Arial\", 10, \"bold\"))\n        console_label.pack(anchor=tk.W, padx=10, pady=(10, 5))\n        \n        console_frame = ttk.Frame(self.root)\n        console_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=(0, 10))\n        \n        scrollbar = ttk.Scrollbar(console_frame)\n        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)\n        \n        self.output_text = tk.Text(console_frame, height=8, yscrollcommand=scrollbar.set, bg=\"#1e1e1e\", fg=\"#00ff00\", font=(\"Courier\", 9))\n        self.output_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)\n        scrollbar.config(command=self.output_text.yview)\n    \n    def setup_config_tab(self, parent):\n        # Android Device Configuration\n        android_lf = ttk.LabelFrame(parent, text=\"Android Device\", padding=10)\n        android_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Label(android_lf, text=\"Device IP:\").grid(row=0, column=0, sticky=tk.W, pady=5)\n        ttk.Entry(android_lf, textvariable=self.device_ip, width=30).grid(row=0, column=1, sticky=tk.EW, padx=5)\n        \n        ttk.Label(android_lf, text=\"Port:\").grid(row=1, column=0, sticky=tk.W, pady=5)\n        ttk.Entry(android_lf, textvariable=self.device_port, width=30).grid(row=1, column=1, sticky=tk.EW, padx=5)\n        \n        android_lf.columnconfigure(1, weight=1)\n        \n        # Laptop Configuration\n        laptop_lf = ttk.LabelFrame(parent, text=\"Laptop / Remote Host\", padding=10)\n        laptop_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Label(laptop_lf, text=\"Laptop IP:\").grid(row=0, column=0, sticky=tk.W, pady=5)\n        ttk.Entry(laptop_lf, textvariable=self.laptop_ip, width=30).grid(row=0, column=1, sticky=tk.EW, padx=5)\n        \n        ttk.Label(laptop_lf, text=\"Username:\").grid(row=1, column=0, sticky=tk.W, pady=5)\n        ttk.Entry(laptop_lf, textvariable=self.laptop_user, width=30).grid(row=1, column=1, sticky=tk.EW, padx=5)\n        \n        laptop_lf.columnconfigure(1, weight=1)\n        \n        # Buttons\n        button_frame = ttk.Frame(parent)\n        button_frame.pack(fill=tk.X, padx=10, pady=10)\n        ttk.Button(button_frame, text=\"💾 Save Configuration\", command=self.save_config).pack(side=tk.LEFT, padx=5)\n        ttk.Button(button_frame, text=\"🔄 Refresh\", command=self.load_config).pack(side=tk.LEFT, padx=5)\n    \n    def setup_android_tab(self, parent):\n        # Quick Status\n        status_lf = ttk.LabelFrame(parent, text=\"Device Status\", padding=10)\n        status_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(status_lf, text=\"✅ Check Connected Devices\", command=self.check_devices).pack(fill=tk.X, pady=5)\n        ttk.Button(status_lf, text=\"📊 Get Device Info\", command=self.get_device_info).pack(fill=tk.X, pady=5)\n        ttk.Button(status_lf, text=\"🔄 Restart adb Server\", command=self.restart_adb).pack(fill=tk.X, pady=5)\n        \n        # Wireless Connection\n        wireless_lf = ttk.LabelFrame(parent, text=\"Wireless Debugging Setup\", padding=10)\n        wireless_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(wireless_lf, text=\"📡 Connect via IP (Wi-Fi)\", command=self.connect_wireless).pack(fill=tk.X, pady=5)\n        ttk.Button(wireless_lf, text=\"🔌 Disconnect Device\", command=self.disconnect_device).pack(fill=tk.X, pady=5)\n        \n        # Screen & Control\n        control_lf = ttk.LabelFrame(parent, text=\"Screen & Control\", padding=10)\n        control_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(control_lf, text=\"🎬 Mirror Screen (scrcpy)\", command=self.start_scrcpy).pack(fill=tk.X, pady=5)\n        ttk.Button(control_lf, text=\"📸 Capture Screenshot\", command=self.capture_screenshot).pack(fill=tk.X, pady=5)\n        \n        # Advanced Commands\n        advanced_lf = ttk.LabelFrame(parent, text=\"Advanced Commands\", padding=10)\n        advanced_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(advanced_lf, text=\"📋 View Logcat (Logs)\", command=self.view_logcat).pack(fill=tk.X, pady=5)\n        ttk.Button(advanced_lf, text=\"🔄 Reboot Device\", command=self.reboot_device).pack(fill=tk.X, pady=5)\n        ttk.Button(advanced_lf, text=\"📝 List Installed Apps\", command=self.list_apps).pack(fill=tk.X, pady=5)\n    \n    def setup_laptop_tab(self, parent):\n        ssh_lf = ttk.LabelFrame(parent, text=\"SSH Remote Access\", padding=10)\n        ssh_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(ssh_lf, text=\"🖥️  SSH Terminal Connection\", command=self.ssh_terminal).pack(fill=tk.X, pady=5)\n        ttk.Button(ssh_lf, text=\"📁 SSH File Transfer (SFTP)\", command=self.sftp_connection).pack(fill=tk.X, pady=5)\n        ttk.Button(ssh_lf, text=\"🔐 SSH Key Setup Guide\", command=self.ssh_key_guide).pack(fill=tk.X, pady=5)\n        \n        vnc_lf = ttk.LabelFrame(parent, text=\"VNC Remote Desktop\", padding=10)\n        vnc_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(vnc_lf, text=\"🖱️  VNC Viewer Connection\", command=self.vnc_viewer).pack(fill=tk.X, pady=5)\n        ttk.Button(vnc_lf, text=\"📺 X11VNC Server Setup\", command=self.x11vnc_setup).pack(fill=tk.X, pady=5)\n        \n        network_lf = ttk.LabelFrame(parent, text=\"Network & Tunneling\", padding=10)\n        network_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(network_lf, text=\"🌐 Ping Laptop Host\", command=self.ping_laptop).pack(fill=tk.X, pady=5)\n        ttk.Button(network_lf, text=\"🔒 SSH Port Forwarding\", command=self.ssh_forward).pack(fill=tk.X, pady=5)\n    \n    def setup_monitor_tab(self, parent):\n        # Auto-monitoring\n        monitor_lf = ttk.LabelFrame(parent, text=\"Device Monitoring\", padding=10)\n        monitor_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(monitor_lf, text=\"📊 Run Device Monitor\", command=self.run_monitor).pack(fill=tk.X, pady=5)\n        ttk.Button(monitor_lf, text=\"⏸️  Stop Monitoring\", command=self.stop_monitor).pack(fill=tk.X, pady=5)\n        \n        # Logs\n        logs_lf = ttk.LabelFrame(parent, text=\"Logs & Reports\", padding=10)\n        logs_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(logs_lf, text=\"📂 Open Log Folder\", command=self.open_log_folder).pack(fill=tk.X, pady=5)\n        ttk.Button(logs_lf, text=\"📄 View Latest Log\", command=self.view_latest_log).pack(fill=tk.X, pady=5)\n        ttk.Button(logs_lf, text=\"🗑️  Clear Old Logs\", command=self.clear_logs).pack(fill=tk.X, pady=5)\n        \n        # System Info\n        system_lf = ttk.LabelFrame(parent, text=\"System Information\", padding=10)\n        system_lf.pack(fill=tk.X, padx=10, pady=10)\n        \n        ttk.Button(system_lf, text=\"💻 Network Status\", command=self.network_status).pack(fill=tk.X, pady=5)\n        ttk.Button(system_lf, text=\"🔧 Environment Check\", command=self.check_environment).pack(fill=tk.X, pady=5)\n    \n    def run_command(self, cmd, description=\"\"):\n        \"\"\"Run command in background and display output\"\"\"\n        def execute():\n            self.log_output(f\"\\n▶ {description or ' '.join(cmd)}\\n\" + \"=\"*60)\n            try:\n                result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)\n                if result.stdout:\n                    self.log_output(result.stdout)\n                if result.stderr:\n                    self.log_output(f\"[ERROR] {result.stderr}\")\n                if result.returncode == 0:\n                    self.log_output(\"✅ Command completed successfully\")\n                else:\n                    self.log_output(f\"⚠️  Command exited with code {result.returncode}\")\n            except subprocess.TimeoutExpired:\n                self.log_output(\"⏱️  Command timeout!\")\n            except Exception as e:\n                self.log_output(f\"❌ Error: {str(e)}\")\n        \n        thread = threading.Thread(target=execute, daemon=True)\n        thread.start()\n    \n    def log_output(self, text):\n        \"\"\"Log to console and file\"\"\"\n        self.output_text.insert(tk.END, text + \"\\n\")\n        self.output_text.see(tk.END)\n        self.root.update()\n        \n        # Also save to log file\n        log_file = self.log_dir / f\"control-panel-{datetime.now().strftime('%Y-%m-%d')}.log\"\n        with log_file.open(\"a\", encoding=\"utf-8\") as f:\n            f.write(text + \"\\n\")\n    \n    # Device Commands\n    def check_devices(self):\n        self.run_command([\"adb\", \"devices\", \"-l\"], \"📋 Checking connected devices...\")\n    \n    def get_device_info(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        cmds = [\n            ([\"adb\", \"-s\", device, \"shell\", \"getprop\", \"ro.product.model\"], \"Model\"),\n            ([\"adb\", \"-s\", device, \"shell\", \"getprop\", \"ro.build.version.release\"], \"Android Version\"),\n            ([\"adb\", \"-s\", device, \"shell\", \"getprop\", \"ro.serialno\"], \"Serial Number\"),\n        ]\n        for cmd, desc in cmds:\n            self.run_command(cmd, f\"📊 Getting {desc}...\")\n    \n    def restart_adb(self):\n        self.run_command([\"adb\", \"kill-server\"], \"Killing adb server...\")\n        self.run_command([\"adb\", \"start-server\"], \"🔄 Restarting adb server...\")\n    \n    def connect_wireless(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        self.run_command([\"adb\", \"connect\", device], f\"📡 Connecting to {device}...\")\n    \n    def disconnect_device(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        self.run_command([\"adb\", \"disconnect\", device], f\"Disconnecting {device}...\")\n    \n    def start_scrcpy(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        self.run_command([\"scrcpy\", \"-s\", device], \"🎬 Starting screen mirror...\")\n    \n    def capture_screenshot(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        timestamp = datetime.now().strftime(\"%Y%m%d_%H%M%S\")\n        screenshot_file = self.log_dir / f\"screenshot_{timestamp}.png\"\n        self.run_command(\n            [\"adb\", \"-s\", device, \"exec-out\", \"screencap\", \"-p\"],\n            f\"📸 Capturing screenshot to {screenshot_file}...\"\n        )\n    \n    def view_logcat(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        log_file = self.log_dir / f\"logcat_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt\"\n        self.log_output(f\"📋 Saving logcat to {log_file}\")\n        self.run_command(\n            [\"adb\", \"-s\", device, \"logcat\", \"-d\"],\n            \"📋 Fetching device logs...\"\n        )\n    \n    def reboot_device(self):\n        if messagebox.askyesno(\"Confirm\", \"Reboot the Android device?\"):\n            device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n            self.run_command([\"adb\", \"-s\", device, \"reboot\"], \"🔄 Rebooting device...\")\n    \n    def list_apps(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        self.run_command([\"adb\", \"-s\", device, \"shell\", \"pm\", \"list\", \"packages\"], \"📱 Listing installed apps...\")\n    \n    # Laptop Commands\n    def ssh_terminal(self):\n        user_host = f\"{self.laptop_user.get()}@{self.laptop_ip.get()}\"\n        self.log_output(f\"🖥️  Opening SSH terminal to {user_host}...\")\n        self.log_output(f\"Run in your terminal: ssh {user_host}\")\n        try:\n            subprocess.Popen([\"xterm\", \"-e\", f\"ssh {user_host}\"])\n        except:\n            try:\n                subprocess.Popen([\"gnome-terminal\", \"--\", \"ssh\", user_host])\n            except:\n                messagebox.showinfo(\"SSH Terminal\", f\"Open terminal and run:\\nssh {user_host}\")\n    \n    def sftp_connection(self):\n        user_host = f\"{self.laptop_user.get()}@{self.laptop_ip.get()}\"\n        self.log_output(f\"📁 SFTP to {user_host}...\")\n        self.log_output(f\"Run in terminal: sftp {user_host}\")\n        messagebox.showinfo(\"SFTP Connection\", f\"Open terminal and run:\\nsftp {user_host}\")\n    \n    def ssh_key_guide(self):\n        guide = \"\"\"SSH Key Setup Guide:\n\n1. Generate SSH key (if not exists):\n   ssh-keygen -t rsa -b 4096 -f ~/.ssh/id_rsa\n\n2. Copy key to remote host:\n   ssh-copy-id -i ~/.ssh/id_rsa.pub user@192.168.1.50\n\n3. Test connection:\n   ssh user@192.168.1.50\n\n4. Optional - Add to ~/.ssh/config:\n   Host laptop\n       HostName 192.168.1.50\n       User user\n       IdentityFile ~/.ssh/id_rsa\n\nThen connect with: ssh laptop\n\"\"\"\n        messagebox.showinfo(\"SSH Key Setup\", guide)\n    \n    def vnc_viewer(self):\n        self.log_output(f\"🖱️  Connecting to VNC on {self.laptop_ip.get()}...\")\n        self.log_output(f\"Download and open VNC Viewer, connect to: {self.laptop_ip.get()}:5901\")\n        messagebox.showinfo(\"VNC Viewer\", f\"Connect to: {self.laptop_ip.get()}:5901\")\n    \n    def x11vnc_setup(self):\n        setup = \"\"\"X11VNC Server Setup:\n\n1. Install x11vnc:\n   sudo apt install x11vnc\n\n2. Start VNC server:\n   x11vnc -display :0 -listen localhost -nopw\n\n3. For persistent setup, use systemd service\n\n4. Connect from another machine:\n   vncviewer localhost:5901\n\"\"\"\n        messagebox.showinfo(\"X11VNC Setup\", setup)\n    \n    def ping_laptop(self):\n        self.run_command([\"ping\", \"-c\", \"4\", self.laptop_ip.get()], f\"🌐 Pinging {self.laptop_ip.get()}...\")\n    \n    def ssh_forward(self):\n        user_host = f\"{self.laptop_user.get()}@{self.laptop_ip.get()}\"\n        forward_info = f\"\"\"SSH Port Forwarding Examples:\n\n1. Forward local port to remote:\n   ssh -L 5901:localhost:5901 {user_host}\n\n2. Forward remote port to local:\n   ssh -R 9999:localhost:22 {user_host}\n\n3. Keep connection alive in background:\n   ssh -fN -L 5901:localhost:5901 {user_host}\n\"\"\"\n        messagebox.showinfo(\"SSH Port Forwarding\", forward_info)\n    \n    # Monitoring\n    def run_monitor(self):\n        device = f\"{self.device_ip.get()}:{self.device_port.get()}\"\n        self.is_running = True\n        self.run_command(\n            [\"python3\", \"scripts/adb-monitor.py\", \"--device\", device],\n            \"📊 Starting device monitor...\"\n        )\n    \n    def stop_monitor(self):\n        self.is_running = False\n        self.log_output(\"⏸️  Monitoring stopped\")\n    \n    def open_log_folder(self):\n        self.log_output(f\"📂 Opening {self.log_dir}...\")\n        try:\n            subprocess.Popen([\"xdg-open\", str(self.log_dir)])\n        except:\n            messagebox.showinfo(\"Log Folder\", f\"Open: {self.log_dir}\")\n    \n    def view_latest_log(self):\n        logs = sorted(self.log_dir.glob(\"*.log\"), reverse=True)\n        if logs:\n            latest = logs[0]\n            with latest.open(\"r\") as f:\n                content = f.read()[-2000:]  # Last 2000 chars\n            self.log_output(f\"📄 Latest log ({latest.name}):\\n{content}\")\n        else:\n            messagebox.showinfo(\"Logs\", \"No logs found yet\")\n    \n    def clear_logs(self):\n        if messagebox.askyesno(\"Confirm\", \"Delete all old logs?\"):\n            for log in self.log_dir.glob(\"*.log\"):\n                log.unlink()\n            self.log_output(\"🗑️  Logs cleared\")\n    \n    def network_status(self):\n        self.run_command([\"ifconfig\"], \"💻 Network status...\")\n    \n    def check_environment(self):\n        self.log_output(\"🔧 Environment Check:\\n\")\n        for tool in [\"adb\", \"scrcpy\", \"ssh\", \"python3\"]:\n            result = subprocess.run([\"which\", tool], capture_output=True, text=True)\n            status = \"✅\" if result.returncode == 0 else \"❌\"\n            self.log_output(f\"{status} {tool}: {result.stdout.strip() or 'Not found'}\")\n    \n    # Config Management\n    def save_config(self):\n        config = {\n            \"device_ip\": self.device_ip.get(),\n            \"device_port\": self.device_port.get(),\n            \"laptop_ip\": self.laptop_ip.get(),\n            \"laptop_user\": self.laptop_user.get(),\n        }\n        config_file = Path.home() / \".lab-control\" / \"config.json\"\n        config_file.parent.mkdir(parents=True, exist_ok=True)\n        with config_file.open(\"w\") as f:\n            json.dump(config, f, indent=2)\n        self.log_output(\"💾 Configuration saved\")\n        messagebox.showinfo(\"Success\", \"Configuration saved!\")\n    \n    def load_config(self):\n        config_file = Path.home() / \".lab-control\" / \"config.json\"\n        if config_file.exists():\n            try:\n                with config_file.open(\"r\") as f:\n                    config = json.load(f)\n                self.device_ip.set(config.get(\"device_ip\", \"192.168.1.25\"))\n                self.device_port.set(config.get(\"device_port\", \"5555\"))\n                self.laptop_ip.set(config.get(\"laptop_ip\", \"192.168.1.50\"))\n                self.laptop_user.set(config.get(\"laptop_user\", \"user\"))\n                self.log_output(\"🔄 Configuration loaded\")\n            except Exception as e:\n                self.log_output(f\"⚠️  Error loading config: {e}\")\n\ndef main():\n    root = tk.Tk()\n    app = LabControlPanel(root)\n    root.mainloop()\n\nif __name__ == \"__main__\":\n    main()\n